DELETE FROM cmd.test_clock;
CREATE FUNCTION test.ready_source(k text,p_silent integer DEFAULT 2) RETURNS void LANGUAGE plpgsql AS $$
DECLARE oid uuid; amount bigint;
BEGIN
 oid:=test.actual_command_order(k,true,jsonb_build_object('delivery_mode','at_farm','acceptance_point','tai_vuon','acceptance_facility_id',NULL,'inspection_before_loading',false,'transport_by','seller','silent_accept_hours',p_silent));
 SELECT expected_deposit_vnd+expected_fee_vnd INTO amount FROM core.deposits WHERE order_id=oid;
 PERFORM test.apply_bank_event(test.bank_receipt(k||'-FUND',amount,k||'-REF'));
 PERFORM test.as_login('db_test_system',$q$SELECT set_config('test.c47.delivery',cmd.activate_order_after_deposit(current_setting('test.x.order')::uuid)::text,true)$q$);
 PERFORM set_config('test.c47.order',oid::text,true);
 PERFORM set_config('test.c47.receiver',test.person('Võ Hoàng Phúc')::text,true);
 PERFORM test.as_login('db_test_buyer',$q$SELECT set_config('test.c47.qr',cmd.assign_receiver(current_setting('test.c47.delivery')::uuid,current_setting('test.c47.receiver')::uuid),true)$q$);
 PERFORM test.as_login('db_test_system',$q$SELECT cmd.ready_delivery(current_setting('test.c47.delivery')::uuid)$q$);
 PERFORM test.as_login('db_test_receiver',$q$SELECT cmd.scan_qr(current_setting('test.c47.qr'),'TEST')$q$);
 PERFORM test.as_login('db_test_receiver',$q$SELECT cmd.start_acceptance(current_setting('test.c47.delivery')::uuid)$q$);
END $$;
REVOKE ALL ON FUNCTION test.ready_source(text,integer) FROM PUBLIC;
SELECT test.ready_source('C50OVER');
SELECT set_config('test.c47.doc',test.command_doc('C50OVER-BBNT')::text,true),set_config('test.c47.lines',jsonb_build_array(jsonb_build_object('lot_id',current_setting('test.x.lot')::uuid,'kind','accepted','qty',1050000,'payable_qty',1050000,'unit_price_vnd',23000,'value_vnd',24150000))::text,true);
