SELECT test.as_login('db_test_receiver',$$SELECT test.expect_error('C50 vượt quá dung sai bị chặn dù đồng ý','SELECT cmd.submit_acceptance(current_setting(''test.c47.delivery'')::uuid,1050001,current_setting(''test.c47.doc'')::jsonb,current_setting(''test.c47.lines'')::jsonb,true)','ck_acceptance_overage')$$);
